import chess

PV = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 0}
CTR = (chess.D4, chess.E4, chess.D5, chess.E5)

MOTIF_NAME = 'positional dominance without material deficit'
MOTIF_DESCRIPTION = 'The side to move wins the overall balance of positional features (piece mobility, space, central control, passed pawns, pawn health, bishop pair, rook files, outposts) while not being behind in material.'


def _rr(sq, color):
    r = chess.square_rank(sq)
    return r if color else 7 - r


def _v(d, t):
    if d >= t:
        return 1
    if d <= -t:
        return -1
    return 0


def _feat(board, c):
    pawns = list(board.pieces(chess.PAWN, c))
    ep = list(board.pieces(chess.PAWN, not c))
    pf = [0] * 8
    of = [0] * 8
    for s in pawns:
        pf[chess.square_file(s)] += 1
    for s in ep:
        of[chess.square_file(s)] += 1
    weak = sum(x - 1 for x in pf if x > 1)
    for i in range(8):
        if pf[i] and (i == 0 or pf[i - 1] == 0) and (i == 7 or pf[i + 1] == 0):
            weak += pf[i]
    psc = 0
    for s in pawns:
        fi = chess.square_file(s)
        r = _rr(s, c)
        free = True
        for e in ep:
            if abs(chess.square_file(e) - fi) <= 1 and _rr(e, c) > r:
                free = False
                break
        if free:
            psc += max(1, r - 1)
    mob = 0
    n = 0
    att = set()
    for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        for s in board.pieces(pt, c):
            n += 1
            for t in board.attacks(s):
                att.add(t)
                p = board.piece_at(t)
                if p is None or p.color != c:
                    mob += 1
    for s in pawns:
        for t in board.attacks(s):
            att.add(t)
    rk = 0
    for s in board.pieces(chess.ROOK, c):
        fi = chess.square_file(s)
        if pf[fi] == 0:
            rk += 2 if of[fi] == 0 else 1
        if _rr(s, c) >= 6:
            rk += 1
    ctr = 0
    for t in CTR:
        ctr += len(board.attackers(c, t))
        p = board.piece_at(t)
        if p is not None and p.color == c:
            ctr += 1
    out = 0
    for pt in (chess.KNIGHT, chess.BISHOP):
        for s in board.pieces(pt, c):
            r = _rr(s, c)
            if r < 4:
                continue
            prot = False
            for x in board.attackers(c, s):
                q = board.piece_at(x)
                if q is not None and q.piece_type == chess.PAWN:
                    prot = True
                    break
            if not prot:
                continue
            fi = chess.square_file(s)
            ok = True
            for e in ep:
                if abs(chess.square_file(e) - fi) == 1 and _rr(e, c) > r:
                    ok = False
                    break
            if ok:
                out += 1
    mat = 0
    for pt in PV:
        mat += PV[pt] * len(board.pieces(pt, c))
    space = 0
    for t in att:
        if _rr(t, c) >= 4:
            space += 1
    pair = 1 if len(board.pieces(chess.BISHOP, c)) >= 2 else 0
    return (mat, mob / n if n else 0.0, psc, weak, space, rk, pair, ctr, out)


def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except Exception:
        return False
    if board.king(chess.WHITE) is None or board.king(chess.BLACK) is None:
        return False
    me = board.turn
    a = _feat(board, me)
    b = _feat(board, not me)
    md = a[0] - b[0]
    v = 0
    if md <= -5:
        v -= 6
    elif md <= -3:
        v -= 4
    elif md <= -1:
        v -= 2
    v += _v(a[1] - b[1], 1.0)
    v += _v(a[2] - b[2], 2)
    v += _v(b[3] - a[3], 2)
    v += _v(a[4] - b[4], 3)
    v += _v(a[5] - b[5], 2)
    v += _v(a[6] - b[6], 1)
    v += _v(a[7] - b[7], 2)
    v += _v(a[8] - b[8], 1)
    return v >= 1

import chess

_PV = {chess.PAWN: 1.0, chess.KNIGHT: 3.0, chess.BISHOP: 3.0, chess.ROOK: 5.0, chess.QUEEN: 9.0}

MOTIF_NAME = 'permanent holes in the enemy camp'
MOTIF_DESCRIPTION = 'The side to move controls clearly more permanent weak squares deep in the opponent half - squares that no enemy pawn can ever attack again and that it already covers with at least as many units as the defender - than the opponent controls in its own half, while not being down material.'


def _bal(b, us):
    s = 0.0
    for pt, v in _PV.items():
        s += v * (len(b.pieces(pt, us)) - len(b.pieces(pt, not us)))
    return s


def _rr(sq, color):
    return chess.square_rank(sq) if color == chess.WHITE else 7 - chess.square_rank(sq)


def _holes(b, us):
    them = not us
    top = [-1] * 8
    for p in b.pieces(chess.PAWN, them):
        f = chess.square_file(p)
        r = _rr(p, us)
        if r > top[f]:
            top[f] = r
    total = 0
    for f in range(1, 7):
        for rr in range(4, 7):
            if top[f - 1] > rr or top[f + 1] > rr:
                continue
            rank = rr if us == chess.WHITE else 7 - rr
            sq = chess.square(f, rank)
            occ = b.piece_at(sq)
            if occ is not None and (occ.color == them or occ.piece_type == chess.PAWN):
                continue
            ours = b.attackers(us, sq)
            if not ours:
                continue
            theirs = b.attackers(them, sq)
            extra = 1 if occ is not None else 0
            if len(ours) + extra < len(theirs):
                continue
            w = 1
            for a in ours:
                pc = b.piece_at(a)
                if pc is not None and pc.piece_type == chess.PAWN:
                    w += 1
                    break
            if rr >= 5:
                w += 1
            total += w
            if total >= 14:
                return total
    return total


def motif(fen: str) -> bool:
    b = chess.Board(fen)
    us = b.turn
    if b.is_check():
        return False
    if b.king(us) is None or b.king(not us) is None:
        return False
    if _bal(b, us) < -1.0:
        return False
    su = _holes(b, us)
    if su < 3:
        return False
    st = _holes(b, not us)
    return su - st >= 2

import chess

_V = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500,
      chess.QUEEN: 950}

MOTIF_NAME = 'superior pawn structure and passed pawn edge'
MOTIF_DESCRIPTION = ('The side to move has a clearly healthier pawn skeleton than the opponent - '
                     'more or further advanced passed pawns and fewer isolated, doubled, backward '
                     'or scattered pawns - while not being down significant material.')


def _mat(board, color):
    s = 0
    for pt, v in _V.items():
        s += v * len(board.pieces(pt, color))
    return s


def _rr(sq, color):
    r = chess.square_rank(sq)
    return r if color == chess.WHITE else 7 - r


def _pawn_support(board, sq, color):
    n = 0
    for a in board.attackers(color, sq):
        p = board.piece_at(a)
        if p is not None and p.piece_type == chess.PAWN:
            n += 1
    return n


def _score(board, color):
    pawns = list(board.pieces(chess.PAWN, color))
    if not pawns:
        return -1.0
    opp = not color
    own = {}
    for sq in pawns:
        own.setdefault(chess.square_file(sq), []).append(sq)
    ofiles = {}
    for sq in board.pieces(chess.PAWN, opp):
        ofiles.setdefault(chess.square_file(sq), []).append(_rr(sq, color))
    sc = 0.0
    for sq in pawns:
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        rr = _rr(sq, color)
        ahead = 0
        blocked_file = False
        for df in (-1, 0, 1):
            nf = f + df
            if 0 <= nf <= 7:
                for orr in ofiles.get(nf, ()):
                    if orr > rr:
                        ahead += 1
                        if df == 0:
                            blocked_file = True
        if ahead == 0:
            sc += 1.0 + 0.55 * max(0, rr - 2)
            if _pawn_support(board, sq, color) > 0:
                sc += 0.5
            fr = r + 1 if color == chess.WHITE else r - 1
            if 0 <= fr <= 7:
                fp = board.piece_at(chess.square(f, fr))
                if fp is not None and fp.color == opp:
                    sc -= 0.4
        isolated = (f - 1) not in own and (f + 1) not in own
        if isolated:
            sc -= 1.0
        elif not blocked_file:
            atk = 0
            for a in board.attackers(opp, sq):
                p = board.piece_at(a)
                if p is not None and p.piece_type == chess.PAWN:
                    atk += 1
            if atk > 0 and _pawn_support(board, sq, color) < atk:
                sc -= 0.7
    for f in own:
        if len(own[f]) > 1:
            sc -= 0.8 * (len(own[f]) - 1)
    fl = sorted(own.keys())
    isl = 1
    for i in range(1, len(fl)):
        if fl[i] != fl[i - 1] + 1:
            isl += 1
    sc -= 0.4 * (isl - 1)
    return sc


def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except Exception:
        return False
    stm = board.turn
    opp = not stm
    if _mat(board, stm) - _mat(board, opp) < -150:
        return False
    return _score(board, stm) - _score(board, opp) >= 1.5

import chess
import math

MOTIF_NAME = "enemy king stranded without shelter"

MOTIF_DESCRIPTION = (
    "With plenty of pieces still on the board and no material deficit for the side to move, "
    "the opponent's king is far worse sheltered than the king of the side to move: it sits on or "
    "near the central files, has lost the right to castle without reaching a corner, has drifted "
    "off its home rank, is missing the pawns that should stand in front of it, stands beside open "
    "or semi-open files, and/or is surrounded by enemy pieces. The side to move owns real attacking "
    "material (a queen or rook plus other pieces), so the exposed king is a concrete target."
)

PIECE_VALUE = {
    chess.PAWN: 1,
    chess.KNIGHT: 3,
    chess.BISHOP: 3,
    chess.ROOK: 5,
    chess.QUEEN: 9,
}


def _material(board: chess.Board, color: bool) -> int:
    total = 0
    for piece_type, value in PIECE_VALUE.items():
        total += value * len(board.pieces(piece_type, color))
    return total


def _non_pawn_material(board: chess.Board, color: bool) -> int:
    total = 0
    for piece_type in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        total += PIECE_VALUE[piece_type] * len(board.pieces(piece_type, color))
    return total


def _heavy_on_file(board: chess.Board, color: bool, file_index: int) -> bool:
    for piece_type in (chess.ROOK, chess.QUEEN):
        for square in board.pieces(piece_type, color):
            if chess.square_file(square) == file_index:
                return True
    return False


def _shield_files(board: chess.Board, color: bool, king_square: int) -> int:
    """How many of the three files around the king have a friendly pawn in front."""
    king_file = chess.square_file(king_square)
    king_rank = chess.square_rank(king_square)
    covered = 0
    for delta_file in (-1, 0, 1):
        file_index = king_file + delta_file
        if not 0 <= file_index <= 7:
            continue
        for step in (1, 2):
            rank_index = king_rank + step if color == chess.WHITE else king_rank - step
            if not 0 <= rank_index <= 7:
                continue
            piece = board.piece_at(chess.square(file_index, rank_index))
            if piece is not None and piece.piece_type == chess.PAWN and piece.color == color:
                covered += 1
                break
    return covered


def _king_zone(king_square: int) -> list:
    king_file = chess.square_file(king_square)
    king_rank = chess.square_rank(king_square)
    zone = []
    for delta_file in (-2, -1, 0, 1, 2):
        for delta_rank in (-2, -1, 0, 1, 2):
            file_index = king_file + delta_file
            rank_index = king_rank + delta_rank
            if 0 <= file_index <= 7 and 0 <= rank_index <= 7:
                zone.append(chess.square(file_index, rank_index))
    return zone


def _king_danger(board: chess.Board, color: bool) -> float:
    king_square = board.king(color)
    if king_square is None:
        return 0.0

    enemy = not color
    king_file = chess.square_file(king_square)
    king_rank = chess.square_rank(king_square)
    score = 0.0

    # Central files offer no shelter.
    if king_file in (3, 4):
        score += 3.0
    elif king_file in (2, 5):
        score += 1.0

    # A king that has left its home rank is walking into the open.
    home_rank = 0 if color == chess.WHITE else 7
    advance = abs(king_rank - home_rank)
    if advance == 1:
        score += 1.0
    elif advance >= 2:
        score += 1.0 + 1.5 * (advance - 1)

    # Castling rights are reassuring; losing them without getting tucked away is not.
    can_castle = (
        board.has_kingside_castling_rights(color)
        or board.has_queenside_castling_rights(color)
    )
    tucked = advance == 0 and king_file in (0, 1, 2, 6, 7)
    if can_castle:
        score -= 1.0
    elif not tucked:
        score += 1.5

    # Missing pawn cover in front of the king.
    score += 1.25 * (3 - _shield_files(board, color, king_square))

    # Open / semi-open files next to the king, worse when enemy heavy pieces aim there.
    for delta_file in (-1, 0, 1):
        file_index = king_file + delta_file
        if not 0 <= file_index <= 7:
            continue
        own_pawn = False
        enemy_pawn = False
        for rank_index in range(8):
            piece = board.piece_at(chess.square(file_index, rank_index))
            if piece is not None and piece.piece_type == chess.PAWN:
                if piece.color == color:
                    own_pawn = True
                else:
                    enemy_pawn = True
        if not own_pawn:
            score += 1.0
            if not enemy_pawn:
                score += 0.5
            if _heavy_on_file(board, enemy, file_index):
                score += 1.5

    # Enemy pieces already swarming the king's neighbourhood.
    attacker_squares = set()
    for square in _king_zone(king_square):
        for attacker_square in board.attackers(enemy, square):
            attacker_squares.add(attacker_square)
    swarm = 0
    for square in attacker_squares:
        piece = board.piece_at(square)
        if piece is not None and piece.piece_type not in (chess.PAWN, chess.KING):
            swarm += 1
    score += 0.75 * swarm

    return score


def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except ValueError:
        return False

    us = board.turn
    them = not us

    if board.king(us) is None or board.king(them) is None:
        return False

    # Not a finished position.
    if board.is_checkmate() or board.is_stalemate() or board.is_insufficient_material():
        return False

    # "Plenty of pieces still on the board".
    if len(board.piece_map()) < 12:
        return False

    # The side to move must own real attacking material.
    if _non_pawn_material(board, us) < 9:
        return False
    if len(board.pieces(chess.QUEEN, us)) + len(board.pieces(chess.ROOK, us)) == 0:
        return False

    # No material deficit worth more than a pawn.
    if _material(board, us) < _material(board, them) - 1:
        return False

    our_danger = _king_danger(board, us)
    their_danger = _king_danger(board, them)

    return their_danger >= 5.0 and (their_danger - our_danger) >= 4.0

import chess

_V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 10}


def _rel(sq, c):
    r = chess.square_rank(sq)
    return r if c else 7 - r


def _mat(b, c):
    s = 0
    for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        s += _V[pt] * len(b.pieces(pt, c))
    return s


def _pawn_hits(b, sq, c):
    for a in b.attackers(c, sq):
        p = b.piece_at(a)
        if p is not None and p.piece_type == chess.PAWN:
            return True
    return False


def _push_hit(b, sq, c):
    f = chess.square_file(sq)
    r = chess.square_rank(sq)
    d = 1 if c else -1
    home = 1 if c else 6
    for df in (-1, 1):
        ff = f + df
        if ff < 0 or ff > 7:
            continue
        for steps in (1, 2):
            pr = r - d * (steps + 1)
            if pr < 0 or pr > 7:
                continue
            if steps == 2 and pr != home:
                continue
            p = b.piece_at(chess.square(ff, pr))
            if p is None or p.piece_type != chess.PAWN or p.color != c:
                continue
            ok = True
            for k in range(1, steps + 1):
                if b.piece_at(chess.square(ff, pr + d * k)) is not None:
                    ok = False
                    break
            if ok:
                return True
    return False


def _safe(b, sq, c, v):
    opp = not c
    if _pawn_hits(b, sq, opp) or _push_hit(b, sq, opp):
        return False
    atts = b.attackers(opp, sq)
    if not atts:
        return True
    mn = 99
    for a in atts:
        w = _V[b.piece_at(a).piece_type]
        if w < mn:
            mn = w
    if mn < v:
        return False
    defs = b.attackers(c, sq)
    if not defs:
        return False
    return len(atts) <= len(defs) + 1


def _no_pawn_ever(b, sq, c):
    f = chess.square_file(sq)
    rr = _rel(sq, c)
    for p in b.pieces(chess.PAWN, not c):
        if abs(chess.square_file(p) - f) == 1 and _rel(p, c) > rr:
            return False
    return True


def _score(b, c):
    opp = not c
    tot = 0
    for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        v = _V[pt]
        for sq in b.pieces(pt, c):
            rr = _rel(sq, c)
            if rr < 4:
                continue
            if not _safe(b, sq, c, v):
                continue
            hits = 0
            free = 0
            for t in b.attacks(sq):
                tp = b.piece_at(t)
                if tp is None:
                    if _pawn_hits(b, t, opp):
                        continue
                    bad = False
                    for a in b.attackers(opp, t):
                        if _V[b.piece_at(a).piece_type] < v:
                            bad = True
                            break
                    if not bad:
                        free += 1
                elif tp.color == opp and tp.piece_type != chess.PAWN:
                    hits += 1
            if free < 2 and hits == 0:
                continue
            s = rr - 3
            if hits:
                s += 1
            if _pawn_hits(b, sq, c):
                s += 1
            if pt in (chess.KNIGHT, chess.BISHOP) and _no_pawn_ever(b, sq, c):
                s += 1
            if pt in (chess.ROOK, chess.QUEEN) and rr >= 6:
                s += 1
            tot += s
    return tot


MOTIF_NAME = 'safe piece infiltration in enemy territory'
MOTIF_DESCRIPTION = 'The side to move has clearly more securely posted active pieces inside the opponent half - units that no enemy pawn can hit now or after one push, that cannot be profitably captured, and that still have targets or free squares - than the opponent has in its own half, while not being down material.'


def motif(fen: str) -> bool:
    try:
        b = chess.Board(fen)
    except Exception:
        return False
    us = b.turn
    them = not us
    if b.king(us) is None or b.king(them) is None:
        return False
    if b.is_check():
        return False
    if _mat(b, us) - _mat(b, them) < -1:
        return False
    a = _score(b, us)
    d = _score(b, them)
    return a >= 2 and a - d >= 2

import chess

_V = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500, chess.QUEEN: 900}

MOTIF_NAME = 'space-gaining pawn wedge in the centre'
MOTIF_DESCRIPTION = 'The side to move owns a clear space advantage: several of its pawns (at least one on a central file) stand on the fourth rank or beyond and grip squares in the opponent half, none of these advanced pawns is over-attacked, and it is not behind in material.'


def _rr(sq, c):
    r = chess.square_rank(sq)
    return r if c else 7 - r


def _mat(b, c):
    t = 0
    for pt in _V:
        t += _V[pt] * len(b.pieces(pt, c))
    return t


def _space(b, c):
    s = 0
    n = 0
    for sq in b.pieces(chess.PAWN, c):
        r = _rr(sq, c)
        f = chess.square_file(sq)
        if r >= 3:
            n += 1
            w = 2 if r >= 4 else 1
            if 2 <= f <= 5:
                w *= 2
            s += w
        for t in b.attacks(sq):
            if _rr(t, c) >= 4:
                s += 1
    return s, n


def motif(fen: str) -> bool:
    try:
        b = chess.Board(fen)
    except Exception:
        return False
    if b.is_check():
        return False
    us = b.turn
    them = not us
    if not b.pieces(chess.PAWN, us):
        return False
    if _mat(b, us) - _mat(b, them) < -60:
        return False
    su, nu = _space(b, us)
    st, nt = _space(b, them)
    if su - st < 5 or su < 6:
        return False
    if nu < 2 or nu < nt:
        return False
    core = False
    for sq in b.pieces(chess.PAWN, us):
        if _rr(sq, us) < 3:
            continue
        if len(b.attackers(them, sq)) > len(b.attackers(us, sq)):
            return False
        if 2 <= chess.square_file(sq) <= 5:
            core = True
    return core

import chess

MOTIF_NAME = 'opponent starved of forcing resources'
MOTIF_DESCRIPTION = 'The side to move owns concrete forcing resources - a capture that wins material, a safe check, a safe pawn push that hits an enemy piece, or a promotion - while the opponent, even if handed a free move, would have none or far fewer of them, so the whole initiative belongs to the side to move.'

V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 100}


def _mat(b, c):
    t = 0
    for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        t += V[pt] * len(b.pieces(pt, c))
    return t


def _pawn_hits(sq, col):
    f = chess.square_file(sq)
    r = chess.square_rank(sq) + (1 if col == chess.WHITE else -1)
    out = []
    if 0 <= r <= 7:
        if f > 0:
            out.append(chess.square(f - 1, r))
        if f < 7:
            out.append(chess.square(f + 1, r))
    return out


def _safe(b, frm, to, pt, us):
    them = not us
    atk = list(b.attackers(them, to))
    if not atk:
        return True
    defs = [d for d in b.attackers(us, to) if d != frm]
    val = V[pt]
    for a in atk:
        p = b.piece_at(a)
        if p is None:
            continue
        if p.piece_type == chess.KING:
            if not defs:
                return False
            continue
        if V[p.piece_type] < val:
            return False
    return bool(defs)


def _res(b):
    us = b.turn
    them = not us
    n = 0
    for m in b.legal_moves:
        if m.promotion is not None and m.promotion != chess.QUEEN:
            continue
        pc = b.piece_at(m.from_square)
        if pc is None:
            continue
        pt = pc.piece_type
        cap = b.is_capture(m)
        good = False
        if cap:
            vic = b.piece_at(m.to_square)
            vv = 1 if vic is None else V[vic.piece_type]
            defs = [d for d in b.attackers(them, m.to_square) if d != m.from_square]
            if (vv if not defs else vv - V[pt]) >= 1:
                good = True
        if (not good) and m.promotion == chess.QUEEN:
            if _safe(b, m.from_square, m.to_square, chess.QUEEN, us):
                good = True
        if (not good) and b.gives_check(m):
            if _safe(b, m.from_square, m.to_square, pt, us):
                good = True
        if (not good) and pt == chess.PAWN and not cap:
            if _safe(b, m.from_square, m.to_square, pt, us):
                for h in _pawn_hits(m.to_square, us):
                    q = b.piece_at(h)
                    if q is not None and q.color == them and q.piece_type not in (chess.PAWN, chess.KING):
                        good = True
                        break
        if good:
            n += 1
            if n >= 6:
                break
    return n


def motif(fen: str) -> bool:
    b = chess.Board(fen)
    us = b.turn
    them = not us
    if b.king(us) is None or b.king(them) is None:
        return False
    if b.is_check():
        return False
    if _mat(b, us) < _mat(b, them) - 1:
        return False
    mine = _res(b)
    if mine < 1:
        return False
    b.push(chess.Move.null())
    theirs = _res(b)
    b.pop()
    if theirs == 0:
        return True
    return mine - theirs >= 3

import chess

MOTIF_NAME = 'own camp free of enemy pressure'
MOTIF_DESCRIPTION = 'The side to move has nothing concrete to worry about at home: none of its pieces is hanging, harassed by a cheaper unit, over-attacked or pinned, no enemy piece or far advanced enemy pawn sits unchallenged inside its own half, and at most one enemy piece eyes the squares around its king.'

_V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 100}
_PIECES = (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN)


def _rel(sq, side):
    r = chess.square_rank(sq)
    return r if side == chess.WHITE else 7 - r


def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except Exception:
        return False
    if board.is_check():
        return False
    us = board.turn
    them = not us
    k = board.king(us)
    if k is None or board.king(them) is None:
        return False

    npm = 0
    for pt in _PIECES:
        npm += _V[pt] * len(board.pieces(pt, them))
    if npm < 6:
        return False

    # our own pieces must not be pinned, hanging, harassed or over-attacked
    for pt in _PIECES:
        for sq in board.pieces(pt, us):
            if board.is_pinned(us, sq):
                return False
            atts = board.attackers(them, sq)
            if not atts:
                continue
            defs = board.attackers(us, sq)
            cheap = 100
            for a in atts:
                pc = board.piece_at(a)
                if pc is not None and _V[pc.piece_type] < cheap:
                    cheap = _V[pc.piece_type]
            if cheap < _V[pt]:
                return False
            if len(defs) == 0:
                return False
            if len(atts) > len(defs):
                return False

    # no own pawn is ganged up on
    for sq in board.pieces(chess.PAWN, us):
        atts = board.attackers(them, sq)
        if len(atts) >= 2 and len(atts) > len(board.attackers(us, sq)):
            return False

    # no unchallenged enemy piece lodged in our half
    for pt in _PIECES:
        for sq in board.pieces(pt, them):
            if _rel(sq, us) <= 3 and not board.attackers(us, sq):
                return False

    # no unchallenged far advanced enemy pawn
    for sq in board.pieces(chess.PAWN, them):
        if _rel(sq, us) <= 2 and not board.attackers(us, sq):
            return False

    # little enemy presence around our king
    ring = board.attacks(k)
    cnt = 0
    for pt in _PIECES:
        for sq in board.pieces(pt, them):
            if board.attacks(sq) & ring:
                cnt += 1
    return cnt <= 1

import chess

MOTIF_NAME = 'opponent lags in mobilization and king shelter'
MOTIF_DESCRIPTION = 'With plenty of pieces still on the board and without being down material, the side to move is clearly better mobilized than the opponent: fewer minor pieces still on the first rank, less back-rank clutter, no corner-boxed rook, and a king already tucked away or free to castle while the opponent king sits in the centre or has wandered out.'

_VAL = {chess.PAWN: 1.0, chess.KNIGHT: 3.0, chess.BISHOP: 3.0, chess.ROOK: 5.0, chess.QUEEN: 9.0}


def _rr(sq, color):
    r = chess.square_rank(sq)
    return r if color == chess.WHITE else 7 - r


def _shelter(b, k, color):
    f = chess.square_file(k)
    rr = _rr(k, color)
    n = 0
    for df in (-1, 0, 1):
        ff = f + df
        if ff < 0 or ff > 7:
            continue
        for dr in (1, 2):
            t = rr + dr
            if t > 7:
                break
            rank = t if color == chess.WHITE else 7 - t
            p = b.piece_at(chess.square(ff, rank))
            if p is not None and p.piece_type == chess.PAWN and p.color == color:
                n += 1
                break
    return n


def _can_tuck(b, color):
    hr = 0 if color == chess.WHITE else 7
    if b.has_kingside_castling_rights(color):
        if b.piece_at(chess.square(5, hr)) is None and b.piece_at(chess.square(6, hr)) is None:
            return True
    if b.has_queenside_castling_rights(color):
        if (b.piece_at(chess.square(1, hr)) is None and b.piece_at(chess.square(2, hr)) is None
                and b.piece_at(chess.square(3, hr)) is None):
            return True
    return False


def _king_lag(b, color):
    k = b.king(color)
    if k is None:
        return 0.0
    kf = chess.square_file(k)
    krr = _rr(k, color)
    sh = _shelter(b, k, color)
    if krr >= 3:
        return 2.0
    if krr == 2:
        return 1.5
    if kf <= 2 or kf >= 6:
        return 0.0 if sh >= 2 else 0.75
    if krr == 0 and b.has_castling_rights(color):
        return 0.5 if _can_tuck(b, color) else 1.0
    if 3 <= kf <= 4:
        return 2.0
    return 1.25 if sh >= 2 else 1.75


def _minor_lag(b, color):
    n = 0
    for pt in (chess.KNIGHT, chess.BISHOP):
        for sq in b.pieces(pt, color):
            if _rr(sq, color) == 0:
                n += 1
    return n


def _lag(b, color, klag):
    s = klag + float(_minor_lag(b, color))
    back = 0
    for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        for sq in b.pieces(pt, color):
            if _rr(sq, color) == 0:
                back += 1
    if back > 2:
        s += 0.4 * (back - 2)
    if klag > 0.0:
        for sq in b.pieces(chess.ROOK, color):
            if _rr(sq, color) != 0:
                continue
            mob = 0
            for t in b.attacks(sq):
                p = b.piece_at(t)
                if p is None or p.color != color:
                    mob += 1
            if mob <= 1:
                s += 0.5
    return s


def motif(fen: str) -> bool:
    try:
        b = chess.Board(fen)
    except Exception:
        return False
    us = b.turn
    them = not us
    if b.king(us) is None or b.king(them) is None:
        return False
    mu = 0.0
    mt = 0.0
    npm = 0.0
    for pt, v in _VAL.items():
        cu = len(b.pieces(pt, us))
        ct = len(b.pieces(pt, them))
        mu += v * cu
        mt += v * ct
        if pt != chess.PAWN:
            npm += v * (cu + ct)
    if mu - mt < -1.0:
        return False
    if npm < 26.0:
        return False
    force = (2 * len(b.pieces(chess.QUEEN, us)) + len(b.pieces(chess.ROOK, us))
             + len(b.pieces(chess.KNIGHT, us)) + len(b.pieces(chess.BISHOP, us)))
    if force < 4:
        return False
    if b.is_check():
        return False
    ku = _king_lag(b, us)
    kt = _king_lag(b, them)
    lu = _lag(b, us, ku)
    lt = _lag(b, them, kt)
    if lt - lu < 1.5:
        return False
    return kt > ku or _minor_lag(b, them) >= _minor_lag(b, us) + 2

import chess

_V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}

MOTIF_NAME = 'pressure on weak squares around the enemy king'
MOTIF_DESCRIPTION = 'The side to move hits more completely undefended squares in the ring and front zone of the opponent king, with at least two attacking units and more total pressure there than the opponent generates around its own king.'


def _mat(b, c):
    s = 0
    for pt in _V:
        s += _V[pt] * len(b.pieces(pt, c))
    return s


def _zone(b, c):
    k = b.king(c)
    f = chess.square_file(k)
    r = chess.square_rank(k)
    d = 1 if c == chess.WHITE else -1
    out = []
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            if df == 0 and dr == 0:
                continue
            nf = f + df
            nr = r + dr
            if 0 <= nf <= 7 and 0 <= nr <= 7:
                out.append(chess.square(nf, nr))
    nr2 = r + 2 * d
    if 0 <= nr2 <= 7:
        for df in (-2, -1, 0, 1, 2):
            nf = f + df
            if 0 <= nf <= 7:
                out.append(chess.square(nf, nr2))
    return out


def _guards(b, color, sq):
    n = 0
    for x in b.attackers(color, sq):
        p = b.piece_at(x)
        if p is not None and p.piece_type != chess.KING:
            n += 1
    return n


def _report(b, atk, dfn):
    press = 0
    weak = 0
    movers = set()
    for s in _zone(b, dfn):
        a = 0
        for x in b.attackers(atk, s):
            p = b.piece_at(x)
            if p is not None and p.piece_type != chess.KING:
                a += 1
                movers.add(x)
        if a == 0:
            continue
        press += a
        if _guards(b, dfn, s) == 0:
            weak += 1
    return press, weak, len(movers)


def motif(fen: str) -> bool:
    b = chess.Board(fen)
    us = b.turn
    them = not us
    if b.king(us) is None or b.king(them) is None:
        return False
    if b.is_check():
        return False
    if _mat(b, us) < _mat(b, them) - 3:
        return False
    pu, wu, mu = _report(b, us, them)
    pt, wt, mt = _report(b, them, us)
    if mu < 2:
        return False
    if wu >= 1 and wu > wt and pu > pt:
        return True
    return pu >= 4 and pu - pt >= 4 and wu >= wt

import chess

PV = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330,
      chess.ROOK: 500, chess.QUEEN: 900}

MOTIF_NAME = 'pressure on the opponent weak pawns'
MOTIF_DESCRIPTION = 'The side to move puts more pressure on the opponent structurally weak or under-defended pawns (and harasses more enemy pieces with its own pawns) than the opponent does in return, while not being materially down.'


def _rr(sq, color):
    r = chess.square_rank(sq)
    return r if color == chess.WHITE else 7 - r


def _mat(board, color):
    t = 0
    for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        t += PV[pt] * len(board.pieces(pt, color))
    return t


def _can_be_pawn_guarded(board, sq, owner):
    f = chess.square_file(sq)
    r = _rr(sq, owner)
    for s2 in board.pieces(chess.PAWN, owner):
        if abs(chess.square_file(s2) - f) == 1 and _rr(s2, owner) < r:
            return True
    return False


def _pressure(board, color):
    opp = not color
    total = 0
    for sq in board.pieces(chess.PAWN, opp):
        rr = _rr(sq, opp)
        if rr > 4:
            continue
        atk = board.attackers(color, sq)
        if not atk:
            continue
        dfn = board.attackers(opp, sq)
        pawn_guard = False
        for d in dfn:
            p = board.piece_at(d)
            if p is not None and p.piece_type == chess.PAWN:
                pawn_guard = True
                break
        w = 0
        if rr >= 2 and not _can_be_pawn_guarded(board, sq, opp):
            w += 1
        if len(atk) > len(dfn) and not pawn_guard:
            w += 2
        if w:
            for a in atk:
                p = board.piece_at(a)
                if (p is not None and p.piece_type in (chess.ROOK, chess.QUEEN)
                        and chess.square_file(a) == chess.square_file(sq)):
                    w += 1
                    break
        total += w
    harass = 0
    for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        for sq in board.pieces(pt, opp):
            for a in board.attackers(color, sq):
                p = board.piece_at(a)
                if p is not None and p.piece_type == chess.PAWN:
                    harass += 1
                    break
    if harass > 2:
        harass = 2
    return total + harass


def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except Exception:
        return False
    stm = board.turn
    opp = not stm
    if _mat(board, stm) - _mat(board, opp) < -150:
        return False
    return _pressure(board, stm) - _pressure(board, opp) >= 2

import chess

MOTIF_NAME = 'opponent saddled with a bad minor piece'
MOTIF_DESCRIPTION = 'The opponent owns at least one clearly poor knight or bishop - almost no safe squares, still stuck on its home rank, rim-bound, or a bishop buried behind its own same-coloured and blocked pawns - while every minor piece of the side to move is healthy, with material roughly balanced.'

_V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}


def _mat(b, c):
    t = 0
    for pt in _V:
        t += _V[pt] * len(b.pieces(pt, c))
    return t


def _pawn_att(b, c):
    s = set()
    for sq in b.pieces(chess.PAWN, c):
        for t in b.attacks(sq):
            s.add(t)
    return s


def _rr(sq, c):
    r = chess.square_rank(sq)
    return r if c == chess.WHITE else 7 - r


def _sc_pawns(b, sq, c):
    par = (chess.square_file(sq) + chess.square_rank(sq)) % 2
    step = 8 if c == chess.WHITE else -8
    n = 0
    blk = 0
    for p in b.pieces(chess.PAWN, c):
        if (chess.square_file(p) + chess.square_rank(p)) % 2 != par:
            continue
        n += 1
        f = p + step
        if 0 <= f < 64 and b.piece_at(f) is not None:
            blk += 1
    return n, blk


def _pawn_proof(b, sq, c):
    them = not c
    f = chess.square_file(sq)
    r = chess.square_rank(sq)
    for df in (-1, 1):
        nf = f + df
        if nf < 0 or nf > 7:
            continue
        for p in b.pieces(chess.PAWN, them):
            if chess.square_file(p) != nf:
                continue
            pr = chess.square_rank(p)
            if c == chess.WHITE and pr > r:
                return False
            if c == chess.BLACK and pr < r:
                return False
    return True


def _quality(b, sq, c, epa):
    pc = b.piece_at(sq)
    if pc is None:
        return 9.0
    q = 0.0
    for t in b.attacks(sq):
        p = b.piece_at(t)
        if p is not None and p.color == c:
            continue
        if t in epa:
            continue
        q += 1.0
    rr = _rr(sq, c)
    if pc.piece_type == chess.BISHOP:
        n, blk = _sc_pawns(b, sq, c)
        if n > 3:
            q -= float(n - 3)
        q -= 0.5 * blk
        if rr == 0:
            q -= 1.0
    else:
        if rr == 0:
            q -= 2.0
        if chess.square_file(sq) in (0, 7):
            q -= 1.0
        if rr >= 4 and len(b.attackers(c, sq) & b.pieces(chess.PAWN, c)) > 0 and _pawn_proof(b, sq, c):
            q += 2.0
    return q


def motif(fen: str) -> bool:
    try:
        b = chess.Board(fen)
    except Exception:
        return False
    us = b.turn
    them = not us
    if b.king(us) is None or b.king(them) is None:
        return False
    md = _mat(b, us) - _mat(b, them)
    if md < -1 or md > 2:
        return False
    ours = list(b.pieces(chess.KNIGHT, us)) + list(b.pieces(chess.BISHOP, us))
    theirs = list(b.pieces(chess.KNIGHT, them)) + list(b.pieces(chess.BISHOP, them))
    if not ours or not theirs:
        return False
    ea = _pawn_att(b, them)
    oa = _pawn_att(b, us)
    qo = [_quality(b, s, us, ea) for s in ours]
    qt = [_quality(b, s, them, oa) for s in theirs]
    lo = min(qo)
    lt = min(qt)
    if lt > 1.0:
        return False
    if lo <= 1.0:
        return False
    return lo - lt >= 2.0

import chess

_VAL = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}

MOTIF_NAME = 'opponent pieces tied to passive defence'
MOTIF_DESCRIPTION = 'The opponent has clearly more pieces stuck in passive defensive duty than the side to move - non-pawn units that must guard an attacked friendly pawn, act as the only guard of an attacked unit, or sit in front of a passed pawn as blockader - while the side to move is not down material.'


def _material(board, color):
    t = 0
    for pt, v in _VAL.items():
        t += v * len(board.pieces(pt, color))
    return t


def _is_passed(board, color, sq):
    f = chess.square_file(sq)
    r = chess.square_rank(sq)
    for ep in board.pieces(chess.PAWN, not color):
        if abs(chess.square_file(ep) - f) > 1:
            continue
        er = chess.square_rank(ep)
        if color == chess.WHITE and er > r:
            return False
        if color == chess.BLACK and er < r:
            return False
    return True


def _duty(board, color):
    opp = not color
    duty = set()
    for sq in chess.SQUARES:
        p = board.piece_at(sq)
        if p is None or p.color != color or p.piece_type == chess.KING:
            continue
        if not board.attackers(opp, sq):
            continue
        defs = board.attackers(color, sq)
        n = len(defs)
        if n == 0:
            continue
        for d in defs:
            dp = board.piece_at(d)
            if dp is None or dp.piece_type == chess.PAWN:
                continue
            if p.piece_type == chess.PAWN or n == 1:
                duty.add(d)
    step = 8 if opp == chess.WHITE else -8
    for ps in board.pieces(chess.PAWN, opp):
        front = ps + step
        if front < 0 or front > 63:
            continue
        fp = board.piece_at(front)
        if fp is None or fp.color != color or fp.piece_type == chess.PAWN:
            continue
        if _is_passed(board, opp, ps):
            duty.add(front)
    return len(duty)


def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except Exception:
        return False
    stm = board.turn
    opp = not stm
    if _material(board, stm) - _material(board, opp) < -1:
        return False
    do = _duty(board, opp)
    ds = _duty(board, stm)
    return do >= 2 and (do - ds) >= 2

import chess

MOTIF_NAME = 'dangerous advanced passed pawn'
MOTIF_DESCRIPTION = 'The side to move owns a clearly more dangerous passed pawn than the opponent - advanced, unblockaded, with a clear or well controlled promotion path and pawn, neighbour-passer or heavy-piece support - while not being down material.'

_V = {chess.PAWN: 1.0, chess.KNIGHT: 3.0, chess.BISHOP: 3.2, chess.ROOK: 5.0, chess.QUEEN: 9.0}


def _mat(b, c):
    t = 0.0
    for pt in _V:
        t += _V[pt] * len(b.pieces(pt, c))
    return t


def _rel(sq, c):
    r = chess.square_rank(sq)
    return r if c == chess.WHITE else 7 - r


def _is_passed(b, sq, c, d, o):
    f = chess.square_file(sq)
    r = chess.square_rank(sq)
    for df in (-1, 0, 1):
        nf = f + df
        if nf < 0 or nf > 7:
            continue
        rr = r + d
        while 0 <= rr <= 7:
            p = b.piece_at(chess.square(nf, rr))
            if p is not None and p.piece_type == chess.PAWN and p.color == o:
                return False
            rr += d
    return True


def _value(b, sq, c, d, o):
    f = chess.square_file(sq)
    r = chess.square_rank(sq)
    v = float(_rel(sq, c))
    stop = chess.square(f, r + d)
    sp = b.piece_at(stop)
    if sp is not None:
        v -= 1.5 if sp.color == o else 0.5
    na = len(b.attackers(o, stop))
    nd = len(b.attackers(c, stop))
    if na > nd:
        v -= 1.0
    elif nd > na:
        v += 0.5
    clear = True
    rr = r + d
    while 0 <= rr <= 7:
        if b.piece_at(chess.square(f, rr)) is not None:
            clear = False
            break
        rr += d
    if clear:
        v += 0.5
    br = r - d
    if 0 <= br <= 7:
        for df in (-1, 1):
            nf = f + df
            if 0 <= nf <= 7:
                p = b.piece_at(chess.square(nf, br))
                if p is not None and p.color == c and p.piece_type == chess.PAWN:
                    v += 0.75
                    break
    rr = r - d
    while 0 <= rr <= 7:
        p = b.piece_at(chess.square(f, rr))
        if p is not None:
            if p.piece_type in (chess.ROOK, chess.QUEEN):
                v += 0.5 if p.color == c else -0.5
            break
        rr -= d
    return v


def _best(b, c):
    o = not c
    d = 1 if c == chess.WHITE else -1
    sqs = []
    for sq in b.pieces(chess.PAWN, c):
        rl = _rel(sq, c)
        if rl < 2 or rl > 6:
            continue
        if _is_passed(b, sq, c, d, o):
            sqs.append(sq)
    files = set()
    for s in sqs:
        files.add(chess.square_file(s))
    best = 0.0
    for sq in sqs:
        v = _value(b, sq, c, d, o)
        f = chess.square_file(sq)
        if (f - 1) in files or (f + 1) in files:
            v += 0.75
        if v > best:
            best = v
    return best


def motif(fen: str) -> bool:
    b = chess.Board(fen)
    us = b.turn
    them = not us
    if _mat(b, us) < _mat(b, them) - 0.5:
        return False
    bu = _best(b, us)
    if bu < 3.5:
        return False
    return bu - _best(b, them) >= 1.5

import chess

_V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 20}

MOTIF_NAME = 'opponent moves keep walking into loss of material'
MOTIF_DESCRIPTION = 'A far larger share of the opponent possible moves would leave the moved piece capturable at a profit than of the side-to-move own moves, while the opponent has no capture that wins more material than the side to move can win, so the opponent is in a bind with hardly any safe option.'


def _scan(board):
    c = board.turn
    e = not c
    unsafe = 0
    total = 0
    best = 0
    for mv in board.legal_moves:
        f = mv.from_square
        d = mv.to_square
        pt = board.piece_type_at(f)
        ct = board.piece_type_at(d)
        gain = _V[ct] if ct is not None else 0
        if ct is None and pt == chess.PAWN and board.is_en_passant(mv):
            gain = 1
        val = _V[mv.promotion] if mv.promotion else _V[pt]
        atk = board.attackers(e, d)
        if gain > 0:
            g = gain - (val if atk else 0)
            if g > best:
                best = g
        if pt == chess.KING:
            continue
        total += 1
        if gain >= val or not atk:
            continue
        cheap = 99
        for s in atk:
            v = _V[board.piece_type_at(s)]
            if v < cheap:
                cheap = v
        sup = 0
        for s in board.attackers(c, d):
            if s != f:
                sup += 1
        if cheap < val or sup == 0:
            unsafe += 1
    return unsafe, total, best


def motif(fen: str) -> bool:
    board = chess.Board(fen)
    if board.king(chess.WHITE) is None or board.king(chess.BLACK) is None:
        return False
    if board.is_check():
        return False
    ua, ta, cap_us = _scan(board)
    board.push(chess.Move.null())
    ub, tb, cap_them = _scan(board)
    board.pop()
    if ta < 10 or tb < 10:
        return False
    if cap_them > cap_us:
        return False
    return (float(ub) / tb) - (float(ua) / ta) >= 0.12

import chess

_V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5,
      chess.QUEEN: 9, chess.KING: 100}

MOTIF_NAME = 'checking initiative against the enemy king'
MOTIF_DESCRIPTION = 'The side to move can deliver more safe checks (checking moves whose piece cannot be profitably captured) than the opponent could deliver if it were their turn, so it owns the forcing initiative.'


def _safe_checks(board):
    mover = board.turn
    foe = not mover
    hits = set()
    for mv in board.legal_moves:
        to = mv.to_square
        if to in hits:
            continue
        pc = board.piece_at(mv.from_square)
        if pc is None:
            continue
        if not board.gives_check(mv):
            continue
        val = _V[mv.promotion] if mv.promotion else _V[pc.piece_type]
        board.push(mv)
        takers = board.attackers(foe, to)
        if not takers:
            hits.add(to)
        else:
            cheap = 200
            for s in takers:
                tp = board.piece_at(s)
                if tp is not None:
                    v = _V[tp.piece_type]
                    if v < cheap:
                        cheap = v
            if cheap >= val and board.attackers(mover, to):
                hits.add(to)
        board.pop()
    return len(hits)


def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except Exception:
        return False
    if board.king(board.turn) is None or board.king(not board.turn) is None:
        return False
    if board.is_check():
        return False
    mine = _safe_checks(board)
    if mine == 0:
        return False
    board.push(chess.Move.null())
    theirs = _safe_checks(board)
    board.pop()
    return mine > theirs

import chess

_V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}

MOTIF_NAME = 'enemy pawn over-extended into our camp'
MOTIF_DESCRIPTION = 'The opponent has a pawn that has pushed past the middle into the side-to-move half where no neighbouring enemy pawn can support it, and the side to move attacks that pawn while either blockading it or outnumbering its defenders, whereas the side to move has no such over-extended pawn itself and is not behind in material.'


def _rr(sq, color):
    r = chess.square_rank(sq)
    return r if color else 7 - r


def _sq(f, rr, color):
    return chess.square(f, rr if color else 7 - rr)


def _supported(board, sq, color):
    f = chess.square_file(sq)
    rr = _rr(sq, color)
    for df in (-1, 1):
        nf = f + df
        if 0 <= nf <= 7:
            for b in (1, 2):
                r2 = rr - b
                if 0 <= r2 <= 7:
                    p = board.piece_at(_sq(nf, r2, color))
                    if p is not None and p.piece_type == chess.PAWN and p.color == color:
                        return True
    return False


def _count(board, side, other):
    n = 0
    for sq in board.pieces(chess.PAWN, side):
        rr = _rr(sq, side)
        if rr < 4:
            continue
        if _supported(board, sq, side):
            continue
        att = len(board.attackers(other, sq))
        if att < 1:
            continue
        dfd = len(board.attackers(side, sq))
        blocked = True
        if rr < 7:
            fs = _sq(chess.square_file(sq), rr + 1, side)
            fp = board.piece_at(fs)
            if fp is None:
                blocked = len(board.attackers(other, fs)) > len(board.attackers(side, fs))
            else:
                blocked = (fp.color == other)
        if att > dfd or blocked:
            n += 1
    return n


def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except Exception:
        return False
    stm = board.turn
    opp = not stm
    m = 0
    for pt, v in _V.items():
        m += v * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
    if m < 0:
        return False
    if len(board.pieces(chess.PAWN, opp)) < 2:
        return False
    if _count(board, opp, stm) < 1:
        return False
    return _count(board, stm, opp) == 0

import chess

VALS = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}
PIECES = (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN)

MOTIF_NAME = 'opponent burdened with two different kinds of weakness'
MOTIF_DESCRIPTION = 'The opponent camp holds targets of at least two different kinds - structurally weak pawns on half-open files, pieces under fire or about to be kicked by a pawn push, and a draughty or centralised king - and clearly more such targets in total than the side to move has at home, while the side to move is not down material.'


def _mat(b, c):
    t = 0
    for pt, v in VALS.items():
        t += v * len(b.pieces(pt, c))
    return t


def _pmap(b, c):
    m = {}
    for s in b.pieces(chess.PAWN, c):
        m.setdefault(chess.square_file(s), []).append(chess.square_rank(s))
    return m


def _pawn_targets(b, d):
    mine = _pmap(b, d)
    opp = _pmap(b, not d)
    fwd = 1 if d == chess.WHITE else -1
    out = 0
    for f in mine:
        if f in opp:
            continue
        ranks = mine[f]
        if (f - 1 not in mine and f + 1 not in mine) or len(ranks) > 1:
            out += 1
            continue
        for r in ranks:
            sq = chess.square(f, r)
            if b.attackers(d, sq) & b.pieces(chess.PAWN, d):
                continue
            back = True
            for af in (f - 1, f + 1):
                for ar in mine.get(af, ()):
                    if (ar - r) * fwd <= 0:
                        back = False
            if back:
                out += 1
    return out


def _hot(b, d):
    o = not d
    out = set()
    for pt in PIECES:
        v = VALS[pt]
        for s in b.pieces(pt, d):
            atk = b.attackers(o, s)
            if not atk:
                continue
            dfn = b.attackers(d, s)
            cheap = False
            for a in atk:
                p = b.piece_at(a)
                if p is not None and VALS.get(p.piece_type, 99) < v:
                    cheap = True
                    break
            if cheap or len(dfn) == 0 or len(atk) > len(dfn):
                out.add(s)
    fwd = 1 if o == chess.WHITE else -1
    for ps in b.pieces(chess.PAWN, o):
        f = chess.square_file(ps)
        r = chess.square_rank(ps)
        r2 = r + fwd
        r3 = r2 + fwd
        if r2 < 0 or r2 > 7 or r3 < 0 or r3 > 7:
            continue
        to = chess.square(f, r2)
        if b.piece_at(to) is not None:
            continue
        if b.attackers(d, to) & b.pieces(chess.PAWN, d):
            continue
        for nf in (f - 1, f + 1):
            if 0 <= nf <= 7:
                t = chess.square(nf, r3)
                p = b.piece_at(t)
                if p is not None and p.color == d and p.piece_type in PIECES:
                    out.add(t)
    return len(out)


def _king_target(b, d):
    k = b.king(d)
    o = not d
    if k is None:
        return 0
    if 2 * len(b.pieces(chess.QUEEN, o)) + len(b.pieces(chess.ROOK, o)) < 2:
        return 0
    kf = chess.square_file(k)
    kr = chess.square_rank(k)
    fwd = 1 if d == chess.WHITE else -1
    shield = 0
    for f in (kf - 1, kf, kf + 1):
        if f < 0 or f > 7:
            continue
        for dr in (0, 1, 2):
            r = kr + fwd * dr
            if 0 <= r <= 7:
                p = b.piece_at(chess.square(f, r))
                if p is not None and p.piece_type == chess.PAWN and p.color == d:
                    shield += 1
                    break
    n = 0
    if shield <= 1:
        n += 1
    if kf in (3, 4) and len(b.pieces(chess.QUEEN, o)) > 0:
        n += 1
    return n


def motif(fen: str) -> bool:
    b = chess.Board(fen)
    us = b.turn
    them = not us
    if b.king(us) is None or b.king(them) is None:
        return False
    if b.is_check():
        return False
    if _mat(b, us) < _mat(b, them) - 1:
        return False
    tp = _pawn_targets(b, them)
    th = _hot(b, them)
    tk = _king_target(b, them)
    cats = (1 if tp > 0 else 0) + (1 if th > 0 else 0) + (1 if tk > 0 else 0)
    if cats < 2:
        return False
    op = _pawn_targets(b, us)
    oh = _hot(b, us)
    ok = _king_target(b, us)
    return (tp + th + tk) - (op + oh + ok) >= 2

import chess
import math

MOTIF_NAME = "favorable piece imbalance without a material lead"
MOTIF_DESCRIPTION = (
    "The side to move has no lead in raw material (standard 1/3/3/5/9 count is level within "
    "half a pawn), yet owns the structurally better army: the bishop pair in an open position, "
    "minor pieces traded against enemy pawns while pieces still dominate, two minors against a "
    "rook, knights in a locked pawn structure, or bishops in an open one. The armies must differ "
    "in composition - identical material on both sides never qualifies."
)

_VALUES = {
    chess.PAWN: 1.0,
    chess.KNIGHT: 3.0,
    chess.BISHOP: 3.0,
    chess.ROOK: 5.0,
    chess.QUEEN: 9.0,
}


def _counts(board, color):
    return {pt: len(board.pieces(pt, color)) for pt in _VALUES}


def _material(counts):
    return sum(_VALUES[pt] * n for pt, n in counts.items())


def _non_pawn_material(counts):
    return sum(_VALUES[pt] * n for pt, n in counts.items() if pt != chess.PAWN)


def _structure(board):
    """Return (total pawns, locked pawn pairs, pawns on both wings flag)."""
    wp = board.pieces(chess.PAWN, chess.WHITE)
    bp = board.pieces(chess.PAWN, chess.BLACK)
    total = len(wp) + len(bp)
    locked = 0
    for sq in wp:
        front = sq + 8
        if front <= 63:
            piece = board.piece_at(front)
            if piece is not None and piece.piece_type == chess.PAWN and piece.color == chess.BLACK:
                locked += 1
    files = set(chess.square_file(sq) for sq in list(wp) + list(bp))
    both_wings = any(f <= 2 for f in files) and any(f >= 5 for f in files)
    return total, locked, both_wings


def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except Exception:
        return False

    if not board.is_valid():
        return False

    us = board.turn
    them = not us

    mine = _counts(board, us)
    theirs = _counts(board, them)

    # Armies must actually differ in composition.
    if all(mine[pt] == theirs[pt] for pt in _VALUES):
        return False

    # No material lead: standard count level within half a pawn.
    diff = _material(mine) - _material(theirs)
    if abs(diff) > 0.5:
        return False

    # Need real pieces on the board for an imbalance to mean anything.
    my_npm = _non_pawn_material(mine)
    their_npm = _non_pawn_material(theirs)
    if my_npm < 3.0 or their_npm < 3.0:
        return False

    total_pawns, locked, both_wings = _structure(board)
    open_position = total_pawns <= 12 and locked <= 1
    closed_position = total_pawns >= 12 and locked >= 2

    my_minors = mine[chess.KNIGHT] + mine[chess.BISHOP]
    their_minors = theirs[chess.KNIGHT] + theirs[chess.BISHOP]
    my_pieces = my_minors + mine[chess.ROOK] + mine[chess.QUEEN]
    their_pieces = their_minors + theirs[chess.ROOK] + theirs[chess.QUEEN]

    score = 0.0

    # 1. Bishop pair advantage, best when the position is open and pawns are spread.
    if mine[chess.BISHOP] >= 2 and theirs[chess.BISHOP] <= 1:
        if open_position:
            score += 1.0
        elif total_pawns <= 13 and locked <= 2:
            score += 0.6
        if both_wings and open_position:
            score += 0.3

    # 2. Minor piece(s) given up by the opponent for pawns: pieces rule while material is full.
    if my_minors > their_minors and theirs[chess.PAWN] - mine[chess.PAWN] >= 3:
        if their_npm >= 6.0 or my_npm >= 9.0:
            score += 1.0

    # 3. Two minor pieces against a rook (plus pawn) with plenty of material left.
    if (my_minors - their_minors) >= 1 and (theirs[chess.ROOK] - mine[chess.ROOK]) >= 1:
        if my_pieces > their_pieces and (my_npm + their_npm) >= 20.0:
            score += 1.0

    # 4. Knights in a closed, locked structure against bishops.
    if closed_position and mine[chess.KNIGHT] > theirs[chess.KNIGHT] and theirs[chess.BISHOP] > mine[chess.BISHOP]:
        score += 1.0

    # 5. Bishops in an open structure against knights.
    if open_position and mine[chess.BISHOP] > theirs[chess.BISHOP] and theirs[chess.KNIGHT] > mine[chess.KNIGHT]:
        score += 1.0
        if both_wings:
            score += 0.3

    # 6. Queen against scattered pieces in a thin, open position.
    if mine[chess.QUEEN] > theirs[chess.QUEEN] and their_pieces > my_pieces and total_pawns <= 10:
        score += 0.6

    return score >= 1.0

import chess

_VW = ((chess.PAWN, 1), (chess.KNIGHT, 3), (chess.BISHOP, 3), (chess.ROOK, 5), (chess.QUEEN, 9))

MOTIF_NAME = 'grip on the opponent weak colour complex'
MOTIF_DESCRIPTION = 'With material roughly level, the side to move keeps a bishop on a colour complex where the opponent has no bishop and few pawns, and grips the resulting unguarded squares of that colour in the opponent camp far more than the opponent grips the other complex.'


def _col(sq):
    return (chess.square_file(sq) + chess.square_rank(sq)) & 1


def _mat(b, c):
    t = 0
    for pt, w in _VW:
        t += w * len(b.pieces(pt, c))
    return t


def _pcover(b, side):
    s = set()
    for sq in b.pieces(chess.PAWN, side):
        s.update(b.attacks(sq))
    return s


def _bish(b, side, c):
    out = []
    for sq in b.pieces(chess.BISHOP, side):
        if _col(sq) == c:
            out.append(sq)
    return out


def _pawns_col(b, side, c):
    n = 0
    for sq in b.pieces(chess.PAWN, side):
        if _col(sq) == c:
            n += 1
    return n


def _complex_score(b, us, them):
    cover = _pcover(b, them)
    best = 0
    for c in (0, 1):
        ob = _bish(b, us, c)
        if not ob:
            continue
        if _bish(b, them, c):
            continue
        if _pawns_col(b, them, c) > 3:
            continue
        holes = 0
        grip = 0
        for sq in chess.SQUARES:
            if _col(sq) != c:
                continue
            rr = chess.square_rank(sq) if them == chess.WHITE else 7 - chess.square_rank(sq)
            if rr < 2 or rr > 4:
                continue
            p = b.piece_at(sq)
            if p is not None and p.color == them and p.piece_type == chess.PAWN:
                continue
            if sq in cover:
                continue
            holes += 1
            if p is not None and p.color == us:
                grip += 2
            else:
                for bs in ob:
                    if sq in b.attacks(bs):
                        grip += 1
                        break
        if holes >= 6 and grip >= 2:
            sc = holes + grip
            if sc > best:
                best = sc
    return best


def motif(fen: str) -> bool:
    try:
        b = chess.Board(fen)
    except Exception:
        return False
    us = b.turn
    them = not us
    if b.king(us) is None or b.king(them) is None:
        return False
    d = _mat(b, us) - _mat(b, them)
    if d > 1 or d < -2:
        return False
    if len(b.pieces(chess.PAWN, them)) < 4:
        return False
    su = _complex_score(b, us, them)
    if su == 0:
        return False
    return su > _complex_score(b, them, us) + 2

import chess

MOTIF_NAME = 'true material edge hidden without a visible lead'
MOTIF_DESCRIPTION = 'The raw count shows no clear material lead for the side to move, yet it is really the one ahead: either it owns the stronger pieces in a material imbalance while standing slightly up on points, or an enemy piece has strayed into the half of the board belonging to the side to move where it has no safe square left and can be attacked more times than it is defended.'

_V = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500, chess.QUEEN: 900}


def _side_material(board, color, with_pawns):
    t = 0
    for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        if pt == chess.PAWN and not with_pawns:
            continue
        t += _V[pt] * len(board.pieces(pt, color))
    return t


def _pval(board, sq):
    p = board.piece_at(sq)
    if p is None:
        return 0
    return _V.get(p.piece_type, 10000)


def _cheapest_att(board, color, sq):
    best = 10000
    for a in board.attackers(color, sq):
        v = _pval(board, a)
        if v < best:
            best = v
    return best


def _safe_stop(board, sq, from_sq, v, owner, foe):
    att = board.attackers(foe, sq)
    n = len(att)
    if n == 0:
        return True
    if _cheapest_att(board, foe, sq) < v:
        return False
    d = 0
    for s in board.attackers(owner, sq):
        if s != from_sq:
            d += 1
    return d >= n


def _boxed_in(board, sq, us, them, v):
    for d in board.attacks(sq):
        p = board.piece_at(d)
        if p is not None:
            if p.color == them:
                continue
            if _V.get(p.piece_type, 10000) >= v:
                return False
        if _safe_stop(board, d, sq, v, them, us):
            return False
    return True


def _wins_target(board, sq, us, them, to_sq, v):
    p = board.piece_at(sq)
    if p is None or p.color != them or _V.get(p.piece_type, 0) != v:
        return False
    na = len(board.attackers(us, sq))
    if na == 0:
        return False
    nd = len(board.attackers(them, sq))
    if na <= nd and _cheapest_att(board, us, sq) >= v:
        return False
    mv_val = _pval(board, to_sq)
    if mv_val > 0:
        oatt = board.attackers(them, to_sq)
        if oatt:
            if _cheapest_att(board, them, to_sq) < mv_val:
                return False
            if len(board.attackers(us, to_sq)) < len(oatt):
                return False
    return _boxed_in(board, sq, us, them, v)


def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except ValueError:
        return False
    us = board.turn
    them = not us
    if board.king(us) is None or board.king(them) is None:
        return False
    diff = _side_material(board, us, True) - _side_material(board, them, True)
    if diff >= 100:
        return False
    pdiff = _side_material(board, us, False) - _side_material(board, them, False)
    if diff >= 20 and pdiff >= 60:
        return True
    if board.is_check():
        return False
    cands = []
    for pt in (chess.QUEEN, chess.ROOK, chess.BISHOP, chess.KNIGHT):
        v = _V[pt]
        if diff + v < 0:
            continue
        for sq in board.pieces(pt, them):
            r = chess.square_rank(sq)
            if us == chess.BLACK:
                r = 7 - r
            if r > 3:
                continue
            na = len(board.attackers(us, sq))
            if na > 0:
                nd = len(board.attackers(them, sq))
                if nd == 0 or na > nd or _cheapest_att(board, us, sq) < v:
                    continue
            if _boxed_in(board, sq, us, them, v):
                cands.append((sq, v))
            if len(cands) >= 2:
                break
        if len(cands) >= 2:
            break
    if not cands:
        return False
    pushes = 0
    for c in cands:
        for mv in board.legal_moves:
            if pushes >= 70:
                return False
            pushes += 1
            board.push(mv)
            ok = _wins_target(board, c[0], us, them, mv.to_square, c[1])
            board.pop()
            if ok:
                return True
    return False

import chess

MOTIF_NAME = 'enemy queen harassed with tempo'
MOTIF_DESCRIPTION = 'The side to move can gain a tempo by safely attacking the opposing queen with a lesser piece, while its own queen cannot be harassed the same way and enjoys at least as many safe squares.'

_V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 100}


def _mat(board, side):
    t = 0
    for pt, v in ((chess.PAWN, 1), (chess.KNIGHT, 3), (chess.BISHOP, 3), (chess.ROOK, 5), (chess.QUEEN, 9)):
        t += v * len(board.pieces(pt, side))
    return t


def _safe_here(board, side, sq):
    p = board.piece_at(sq)
    if p is None:
        return False
    v = _V[p.piece_type]
    atk = board.attackers(not side, sq)
    if not atk:
        return True
    for a in atk:
        q = board.piece_at(a)
        if q is not None and _V[q.piece_type] < v:
            return False
    return len(board.attackers(side, sq)) > 0


def _room(board, side, qsq):
    n = 0
    for m in board.legal_moves:
        if m.from_square != qsq:
            continue
        d = m.to_square
        tgt = board.piece_at(d)
        gain = _V[tgt.piece_type] if tgt is not None else 0
        atk = board.attackers(not side, d)
        if not atk:
            n += 1
            continue
        cheap = False
        for a in atk:
            q = board.piece_at(a)
            if q is not None and _V[q.piece_type] < 9:
                cheap = True
                break
        if cheap:
            if gain >= 8:
                n += 1
            continue
        defs = 0
        for x in board.attackers(side, d):
            if x != qsq:
                defs += 1
        if defs > 0 or gain >= 9:
            n += 1
    return n


def _harass(board, side, tq):
    for m in board.legal_moves:
        if m.to_square == tq:
            continue
        p = board.piece_at(m.from_square)
        if p is None or p.piece_type == chess.QUEEN or p.piece_type == chess.KING:
            continue
        dist = chess.square_distance(m.to_square, tq)
        if p.piece_type == chess.PAWN and dist > 1:
            continue
        if p.piece_type == chess.KNIGHT and dist > 2:
            continue
        board.push(m)
        ok = False
        try:
            if tq in board.attacks(m.to_square):
                ok = _safe_here(board, side, m.to_square)
        finally:
            board.pop()
        if ok:
            return True
    return False


def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except Exception:
        return False
    if board.is_check():
        return False
    us = board.turn
    them = not us
    oq = list(board.pieces(chess.QUEEN, them))
    mq = list(board.pieces(chess.QUEEN, us))
    if len(oq) != 1 or len(mq) != 1:
        return False
    if _mat(board, us) - _mat(board, them) < -1:
        return False
    eq = oq[0]
    myq = mq[0]
    hit_us = _harass(board, us, eq)
    if not hit_us:
        return False
    room_us = _room(board, us, myq)
    board.push(chess.Move.null())
    try:
        hit_them = _harass(board, them, myq)
        room_them = _room(board, them, eq)
    finally:
        board.pop()
    if hit_them:
        return False
    return room_us >= room_them

import chess

MOTIF_NAME = 'stronger double attack threat with nothing hanging'
MOTIF_DESCRIPTION = 'The side to move can make a safe move that sets up a bigger threat package (a fork, a hit on a more valuable or undefended enemy piece, or a threat combined with check) than the best threat the opponent could set up, while none of its own pieces are hanging or attacked by a cheaper unit.'

_V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 100}


def _v(pt):
    return _V.get(pt, 0)


def _cheapest(board, color, sq):
    best = 999
    for a in board.attackers(color, sq):
        p = board.piece_at(a)
        if p is not None:
            val = _v(p.piece_type)
            if val < best:
                best = val
    return best


def _safe_sq(board, sq, us):
    p = board.piece_at(sq)
    if p is None:
        return False
    if p.piece_type == chess.KING:
        return True
    them = not us
    atk = board.attackers(them, sq)
    if not atk:
        return True
    val = _v(p.piece_type)
    if _cheapest(board, them, sq) < val:
        return False
    return len(board.attackers(us, sq)) >= len(atk)


def _threat_score(board, sq, us):
    p = board.piece_at(sq)
    if p is None:
        return 0
    val = _v(p.piece_type)
    them = not us
    s = 0
    for t in board.attacks(sq):
        q = board.piece_at(t)
        if q is None or q.color != them:
            continue
        if q.piece_type == chess.KING:
            s += 1
            continue
        tv = _v(q.piece_type)
        if tv > val or not board.attackers(them, t):
            if tv >= 5:
                s += 3
            elif tv >= 3:
                s += 2
            else:
                s += 1
    return s


def _best_threat(board, us):
    best = 0
    for mv in board.legal_moves:
        board.push(mv)
        if _safe_sq(board, mv.to_square, us):
            s = _threat_score(board, mv.to_square, us)
            if s > best:
                best = s
        board.pop()
        if best >= 6:
            break
    return best


def _hanging(board, us):
    them = not us
    n = 0
    for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        for sq in board.pieces(pt, us):
            if not board.attackers(them, sq):
                continue
            if not board.attackers(us, sq):
                n += 1
            elif _cheapest(board, them, sq) < _v(pt):
                n += 1
    return n


def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except Exception:
        return False
    if board.is_check():
        return False
    us = board.turn
    if _hanging(board, us) > 0:
        return False
    mine = _best_threat(board, us)
    if mine < 3:
        return False
    board.push(chess.Move.null())
    theirs = _best_threat(board, not us)
    board.pop()
    return mine > theirs

import chess

MOTIF_NAME = 'enemy camp riddled with concrete pressure points'
MOTIF_DESCRIPTION = 'With material level or at most a pawn ahead, the side to move creates far more concrete problems in the opponent camp - hanging or pawn-harassed pieces, over-attacked units, pinned targets and pieces held only by a single overloaded or unstable guard - than the opponent creates against it.'

_V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 99}


def _mat(b, c):
    t = 0
    for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        t += _V[pt] * len(b.pieces(pt, c))
    return t


def _cheap(b, sqs):
    m = 99
    for s in sqs:
        p = b.piece_at(s)
        if p is not None and _V[p.piece_type] < m:
            m = _V[p.piece_type]
    return m


def _pressure(b, a, d):
    items = []
    load = {}
    for sq in chess.SQUARES:
        p = b.piece_at(sq)
        if p is None or p.color != d or p.piece_type == chess.KING:
            continue
        atts = list(b.attackers(a, sq))
        if not atts:
            continue
        defs = list(b.attackers(d, sq))
        v = _V[p.piece_type]
        items.append((sq, v, len(atts), defs, _cheap(b, atts)))
        if len(defs) == 1 and v >= 3:
            load[defs[0]] = load.get(defs[0], 0) + 1
    sc = 0
    for sq, v, na, defs, ca in items:
        nd = len(defs)
        if nd == 0:
            sc += 3 if v >= 3 else 1
            continue
        if ca < v:
            sc += 3
            continue
        if na > nd and ca <= v:
            sc += 2
            continue
        if v >= 3 and b.is_pinned(d, sq):
            sc += 2
            continue
        if nd == 1 and v >= 3:
            g = defs[0]
            gp = b.piece_at(g)
            if load.get(g, 0) >= 2 or b.is_pinned(d, g):
                sc += 2
            elif gp is not None and gp.piece_type != chess.KING and \
                    len(b.attackers(a, g)) > len(b.attackers(d, g)):
                sc += 1
    return sc


def motif(fen: str) -> bool:
    try:
        b = chess.Board(fen)
    except Exception:
        return False
    if b.king(chess.WHITE) is None or b.king(chess.BLACK) is None:
        return False
    if b.is_check():
        return False
    us = b.turn
    them = not us
    diff = _mat(b, us) - _mat(b, them)
    if diff < 0 or diff > 1:
        return False
    fu = _pressure(b, us, them)
    ft = _pressure(b, them, us)
    if fu >= 3 and fu - ft >= 2:
        return True
    return fu >= 2 and ft == 0

import chess

_V = {chess.PAWN: 1.0, chess.KNIGHT: 3.0, chess.BISHOP: 3.0, chess.ROOK: 5.0,
      chess.QUEEN: 9.0, chess.KING: 20.0}
_RW = {chess.KNIGHT: 1.0, chess.BISHOP: 1.0, chess.ROOK: 1.2, chess.QUEEN: 1.5}

MOTIF_NAME = 'opponent pieces cornered and hanging'
MOTIF_DESCRIPTION = 'Without holding more than a one-pawn material lead, the side to move troubles the opponent pieces far more than its own are troubled: more enemy knights, bishops, rooks and queens have at most one safe square available, and more of them stand attacked while undefended, hit by a cheaper unit, or attacked more times than defended.'


def _mat(b, c):
    return (len(b.pieces(chess.PAWN, c)) + 3 * len(b.pieces(chess.KNIGHT, c))
            + 3 * len(b.pieces(chess.BISHOP, c)) + 5 * len(b.pieces(chess.ROOK, c))
            + 9 * len(b.pieces(chess.QUEEN, c)))


def _cheap(b, c, sq):
    best = 99.0
    for x in b.attackers(c, sq):
        p = b.piece_at(x)
        if p is not None and _V[p.piece_type] < best:
            best = _V[p.piece_type]
    return best


def _free(b, sq, d, a, v):
    n = 0
    for t in b.attacks(sq):
        occ = b.piece_at(t)
        if occ is not None and occ.color == d:
            continue
        gain = _V[occ.piece_type] if occ is not None else 0.0
        at = b.attackers(a, t)
        if not at or gain >= v - 0.4:
            n += 1
        else:
            c = _cheap(b, a, t)
            if c >= v - 0.4 and b.attackers(d, t):
                n += 1
        if n >= 2:
            return 2
    return n


def _trouble(b, a, d):
    s = 0.0
    for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        v = _V[pt]
        w = _RW[pt]
        for sq in b.pieces(pt, d):
            f = _free(b, sq, d, a, v)
            if f < 2:
                s += w * (2 - f)
            at = b.attackers(a, sq)
            if at:
                df = b.attackers(d, sq)
                if not df or _cheap(b, a, sq) + 0.5 < v:
                    s += 1.2
                elif len(at) > len(df):
                    s += 0.5
    return s


def motif(fen: str) -> bool:
    b = chess.Board(fen)
    us = b.turn
    them = not us
    if b.king(us) is None or b.king(them) is None:
        return False
    if len(b.piece_map()) < 10:
        return False
    if _mat(b, us) - _mat(b, them) > 1:
        return False
    ours = _trouble(b, us, them)
    theirs = _trouble(b, them, us)
    return ours >= 2.0 and (ours - theirs) >= 1.5

import chess

_V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 100}

MOTIF_NAME = 'tempo-gaining threat creation dominance'
MOTIF_DESCRIPTION = 'With material roughly level, the side to move has clearly more quiet moves that safely create a brand-new attack on an enemy unit (hitting it with a cheaper piece or hitting an undefended one) than the opponent can create in reply, so it keeps making threats with tempo.'


def _mat(b, c):
    t = 0
    for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        t += _V[pt] * len(b.pieces(pt, c))
    return t


def _cheapest(b, c, sq):
    best = 100
    for a in b.attackers(c, sq):
        p = b.piece_at(a)
        if p is not None and _V[p.piece_type] < best:
            best = _V[p.piece_type]
    return best


def _lands_safely(b, sq, color, val):
    m = _cheapest(b, not color, sq)
    if m == 100:
        return True
    if m < val:
        return False
    return bool(b.attackers(color, sq))


def _new_threat_targets(b):
    side = b.turn
    opp = not side
    targets = []
    for sq, p in b.piece_map().items():
        if p.color == opp and p.piece_type != chess.KING:
            targets.append((sq, p.piece_type))
    if not targets:
        return 0
    pre = set()
    for sq, pt in targets:
        if b.attackers(side, sq):
            pre.add(sq)
    hits = set()
    for mv in b.legal_moves:
        p = b.piece_at(mv.from_square)
        if p is None or p.piece_type == chess.KING:
            continue
        if b.is_capture(mv):
            continue
        b.push(mv)
        if not b.is_check():
            mover = b.piece_at(mv.to_square)
            if mover is not None:
                val = _V[mover.piece_type]
                att = b.attacks(mv.to_square)
                found = []
                for sq, pt in targets:
                    if sq in pre or sq == mv.to_square or sq in hits:
                        continue
                    q = b.piece_at(sq)
                    if q is None or q.color != opp or q.piece_type != pt:
                        continue
                    if sq not in att:
                        continue
                    if _V[pt] > val or not b.attackers(opp, sq):
                        found.append(sq)
                if found and _lands_safely(b, mv.to_square, side, val):
                    for sq in found:
                        hits.add(sq)
        b.pop()
    return len(hits)


def motif(fen: str) -> bool:
    b = chess.Board(fen)
    us = b.turn
    them = not us
    if b.king(us) is None or b.king(them) is None:
        return False
    if b.is_check():
        return False
    d = _mat(b, us) - _mat(b, them)
    if d > 1 or d < -1:
        return False
    ours = _new_threat_targets(b)
    if ours < 2:
        return False
    b.push(chess.Move.null())
    theirs = _new_threat_targets(b)
    b.pop()
    return ours - theirs >= 2

import chess

MOTIF_NAME = 'more active king in a simplified position'
MOTIF_DESCRIPTION = 'With the queens traded and only a few pieces left, the side to move has the far more active king - more centralized, off its own back rank and closer to the pawns on the board - than the opponent, while not being behind in material.'

_V = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500, chess.QUEEN: 900}
_CTR = (chess.D4, chess.E4, chess.D5, chess.E5)


def _mat(board, color):
    t = 0
    for pt in _V:
        t += _V[pt] * len(board.pieces(pt, color))
    return t


def _cen(sq):
    best = 9
    for c in _CTR:
        d = chess.square_distance(sq, c)
        if d < best:
            best = d
    return best


def _rrank(sq, color):
    r = chess.square_rank(sq)
    return r if color == chess.WHITE else 7 - r


def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except Exception:
        return False

    us = board.turn
    opp = not us

    if board.pieces(chess.QUEEN, chess.WHITE) or board.pieces(chess.QUEEN, chess.BLACK):
        return False

    npieces = 0
    for c in (chess.WHITE, chess.BLACK):
        for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK):
            npieces += len(board.pieces(pt, c))
    if npieces > 8:
        return False

    if _mat(board, us) - _mat(board, opp) < -50:
        return False

    uk = board.king(us)
    ok = board.king(opp)
    if uk is None or ok is None:
        return False
    if board.is_check():
        return False

    pawns = list(board.pieces(chess.PAWN, chess.WHITE)) + list(board.pieces(chess.PAWN, chess.BLACK))
    if len(pawns) < 3:
        return False

    zone = [uk] + list(board.attacks(uk))
    danger = 0
    for sq in zone:
        if board.attackers(opp, sq):
            danger += 1
    if danger >= 4:
        return False
    if npieces >= 7 and danger >= 2:
        return False

    cu = _cen(uk)
    co = _cen(ok)
    if cu > 2:
        return False

    du = 0.0
    do = 0.0
    closer_us = 0
    closer_op = 0
    for p in pawns:
        a = chess.square_distance(uk, p)
        b = chess.square_distance(ok, p)
        du += a
        do += b
        if a < b:
            closer_us += 1
        elif b < a:
            closer_op += 1
    n = float(len(pawns))
    du /= n
    do /= n

    p1 = cu + 1 <= co
    p2 = du + 0.6 <= do
    p3 = closer_us >= closer_op + 2
    p4 = _rrank(uk, us) >= 2 and _rrank(ok, opp) <= 1

    pts = 0
    for f in (p1, p2, p3, p4):
        if f:
            pts += 1

    if not (p1 or p4):
        return False
    return pts >= 2

import chess

VAL = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 100}
BD = ((1, 1), (1, -1), (-1, 1), (-1, -1))
RD = ((1, 0), (-1, 0), (0, 1), (0, -1))

MOTIF_NAME = 'line pressure with pins and x-rays'
MOTIF_DESCRIPTION = 'The side to move owns more line power against the opponent - absolute pins, x-ray alignments where a more valuable enemy unit stands behind a lesser one, sliders stacked in batteries and latent discovered-attack setups - than the opponent has in return.'


def _travels(pt, df, dr):
    if pt == chess.QUEEN:
        return True
    if pt == chess.ROOK:
        return df == 0 or dr == 0
    if pt == chess.BISHOP:
        return df != 0 and dr != 0
    return False


def _lines(board, us, them):
    s = 0
    for pt in (chess.BISHOP, chess.ROOK, chess.QUEEN):
        if pt == chess.BISHOP:
            dirs = BD
        elif pt == chess.ROOK:
            dirs = RD
        else:
            dirs = BD + RD
        for sq in board.pieces(pt, us):
            f0 = chess.square_file(sq)
            r0 = chess.square_rank(sq)
            for df, dr in dirs:
                f = f0 + df
                r = r0 + dr
                fp = None
                fsq = None
                while 0 <= f < 8 and 0 <= r < 8:
                    d = chess.square(f, r)
                    p = board.piece_at(d)
                    if p is not None:
                        if fp is None:
                            if p.color == them and p.piece_type == chess.KING:
                                break
                            fp = p
                            fsq = d
                        else:
                            if p.color == them:
                                if fp.color == them:
                                    if p.piece_type != chess.KING and VAL[p.piece_type] > VAL[fp.piece_type]:
                                        s += 1
                                        if len(board.attackers(us, fsq)) > len(board.attackers(them, fsq)):
                                            s += 1
                                elif _travels(fp.piece_type, df, dr):
                                    s += 1
                                elif p.piece_type in (chess.KING, chess.QUEEN):
                                    s += 1
                            break
                    f += df
                    r += dr
    return s


def _pins(board, us, them):
    s = 0
    for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        for sq in board.pieces(pt, them):
            if board.is_pinned(them, sq):
                if pt == chess.PAWN:
                    s += 1
                elif board.attackers(us, sq):
                    s += 3
                else:
                    s += 2
    return s


def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except Exception:
        return False
    if board.king(chess.WHITE) is None or board.king(chess.BLACK) is None:
        return False
    if board.is_check():
        return False
    us = board.turn
    them = not us
    a = _lines(board, us, them) + _pins(board, us, them)
    if a < 2:
        return False
    b = _lines(board, them, us) + _pins(board, them, us)
    return a - b >= 1
